        {
          "stage": "identity",
          "focus": "商品身份",
          "sentences": [
            {
              "display_text": "这只日常陶瓷马克杯，米白色杯身，带把手，容量三百五十毫升。",
              "spoken_text": "这只日常陶瓷马克杯，米白色杯身，带把手，容量三百五十毫升。",
              "kind": "product_claim",
